import json, os, subprocess, sys, zlib, tempfile
HERE = "/home/c/brix1/b/task126"
SWITCH = os.path.join(HERE, "switch.py")

def mac(m): return bytes(int(x,16) for x in m.split(":"))
def port(name, fc=True, rates=(1000,), modes=("full",), qb=1000000, **kw):
    d = {"name": name, "mode": "access", "pvid": 1, "allowed": [1],
         "untagged": [1], "rates": list(rates), "modes": list(modes),
         "queue_bytes": qb, "flow_control": fc}
    d.update(kw); return d
def cfg(ports, delay=10):
    return {"ports": ports, "age": 100, "max_frame": 1518, "delay": delay}
def link(t,p, rates=(1000,), modes=("full",)):
    return {"t":t,"port":p,"admin":True,"peer":True,"rates":list(rates),"modes":list(modes)}
def adv(t): return {"t":t,"advance":True}
def frame(t,p,dst,src,eth=0x0800,payload=b"", fcs_good=True):
    head = mac(dst)+mac(src)+eth.to_bytes(2,"big")+payload
    fcs = (zlib.crc32(head)&0xffffffff).to_bytes(4,"little") if fcs_good else b"\xff"*4
    return {"t":t,"port":p,"data":(head+fcs).hex()}
def pause(t,p,quanta,reserved_zero=True,opcode=0x0001,length64=True):
    dst="01:80:c2:00:00:01"; src="00:00:00:00:00:01"
    pad_len = 42 if length64 else 10
    body = mac(dst)+mac(src)+b"\x88\x08"+opcode.to_bytes(2,"big")+quanta.to_bytes(2,"big")
    body += (b"\x00" if reserved_zero else b"\x01")*pad_len
    # total without fcs: 6+6+2+2+2+42 = 60; +4 fcs = 64
    fcs = (zlib.crc32(body)&0xffffffff).to_bytes(4,"little")
    return {"t":t,"port":p,"data":(body+fcs).hex()}

def run(cfgdoc, events, *lim, cmd="link-flow-decode"):
    d = tempfile.mkdtemp()
    cp=os.path.join(d,"c.json"); ep=os.path.join(d,"e.json")
    open(cp,"w").write(json.dumps(cfgdoc)); open(ep,"w").write(json.dumps(events))
    pr = subprocess.run([sys.executable, SWITCH, cmd, cp, ep, *map(str,lim)],
                        stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    return pr

# Test 1: basic pause on p1 (up, full, fc on); data frame from p1 floods to p2;
# PAUSE received at p1 affects p1's TX. Send data into p2 so it egresses p1.
c = cfg([port("p1"), port("p2")])
ev = [link(0,"p1"), link(0,"p2"),
      frame(100,"p2","ff:ff:ff:ff:ff:ff","00:00:00:00:00:02",payload=b"x"*46),
      pause(200,"p1",10),
      frame(300,"p2","ff:ff:ff:ff:ff:ff","00:00:00:00:00:02",payload=b"y"*46),
      adv(1000000)]
pr = run(c, ev)
print("T1 rc", pr.returncode, pr.stderr.decode())
if pr.returncode==0:
    out=json.loads(pr.stdout)
    for r in out["results"]: print(r)
    print(out["ports"])
