def accrue_hold(name, now):
    # 按墙钟累计暂停实际生效区间：hold_began 为该区间起点（可为晚于
    # 当前时钟的“在发副本结束时刻”待生效值），截止到有效截止时刻。
    # 结算到截止时刻即关闭；覆盖/清零/离 up 在事件点先经本函数再重置。
    began = hold_began[name]
    if began is None or now <= began:
        return
    until = pause_until[name]
    end = now if until is None else min(now, until)
    if end > began:
        pause_ns[name] += end - began
    hold_began[name] = (
        began if now < began else
        end if until is not None and now < until else None
    )

